interface Divider { func div(int n) where { n != 0 } returns int }
class Calc is Divider { int total
    func div(int amount) returns int { return 100 / amount } }
auto c = Calc.new()
print(c.div(0).to_string())

class Port { int number = 80 where { number > 0, number < 65535 } }
auto p = Port.new()
p.number = 70000
